from collections import defaultdict, deque
edges = [(2,12),(3,10),(6,9),(3,13),(3,12),(0,13),
         (1,4),(1,5),(4,7),(5,8),(7,11),(8,14),(11,14),(0,6),(2,9),(10,11)]
adj = defaultdict(set)
for u,v in edges:
    adj[u].add(v); adj[v].add(u)

# find girth via BFS
girth = float('inf')
for s in range(15):
    dist = {s:0}
    parent = {s:-1}
    q = deque([s])
    while q:
        u = q.popleft()
        for w in adj[u]:
            if w not in dist:
                dist[w] = dist[u]+1
                parent[w] = u
                q.append(w)
            elif parent[u] != w:
                c = dist[u]+dist[w]+1
                if c < girth:
                    girth = c
print("girth:", girth)
